import "./article-header.css";

export interface ArticleHeaderProps {
  category: string;
  title: string;
  standfirst: string;
  authorName: string;
  authorAvatar: string;
  date: string;
  readTime: string;
  align: "left" | "center";
  rule: "on" | "off";
}

export function ArticleHeaderRender({
  category,
  title,
  standfirst,
  authorName,
  authorAvatar,
  date,
  readTime,
  align,
  rule,
}: ArticleHeaderProps) {
  return (
    <div className="p1-article-header p1-block" data-align={align}>
      <div className="p1-article-header__inner">
        {category && <div className="p1-article-header__category">{category}</div>}
        <h1 className="p1-article-header__title">{title}</h1>
        {standfirst && <p className="p1-article-header__standfirst">{standfirst}</p>}
        <div className="p1-article-header__byline">
          <div className="p1-article-header__avatar">
            {authorAvatar && <img src={authorAvatar} alt={authorName} className="p1-article-header__avatar-img" />}
          </div>
          <div className="p1-article-header__author-info">
            <div className="p1-article-header__author-name">{authorName}</div>
            {(date || readTime) && (
              <div className="p1-article-header__meta">
                {date}
                {date && readTime && <span className="p1-article-header__sep">·</span>}
                {readTime}
              </div>
            )}
          </div>
        </div>
        {rule !== "off" && <hr className="p1-article-header__rule" />}
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { ArticleHeaderRender, type ArticleHeaderProps } from "./article-header";
export type { ArticleHeaderProps };

export const ArticleHeaderBlock: ComponentConfig<ArticleHeaderProps> = {
  fields: {
    category: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Category label in 1–3 words. Title case. E.g. Engineering, Product, Community." },
    },
    title: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Article title — compelling and specific, under 15 words." },
    },
    standfirst: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A 1–2 sentence summary of the article. Plain text, no formatting." },
    },
    authorName: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Author's full name." },
    },
    authorAvatar: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { exclude: true },
    },
    date: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Publication date. Format: Month Day, Year. E.g. April 18, 2026." },
    },
    readTime: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Estimated read time. Format: N min read." },
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
    rule: {
      type: "radio" as const,
      options: [
        { label: "On", value: "on" },
        { label: "Off", value: "off" },
      ],
    },
  },
  defaultProps: {
    category: "Engineering",
    title: "What a year of shipping on Multidev taught us about flow.",
    standfirst:
      "A behind-the-scenes look at how the team moved from weeks to hours — and the small habits that made the difference.",
    authorName: "Jordan Ellis",
    authorAvatar: wireframe(200, 200),
    date: "April 18, 2026",
    readTime: "6 min read",
    align: "left",
    rule: "on",
  },
  render: ArticleHeaderRender,
};

export const meta = defineMeta({
  title: 'Article Header',
  description: 'Blog/article masthead with category, title, standfirst, author avatar, date, and read-time; use at the top of editorial pages.',
  categories: ["editorial"],
  published: true,
});

.p1-article-header__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-narrow);
}

.p1-article-header__category {
  color: var(--p1-accent);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.16em;
  margin-block-end: var(--p1-space-md);
  text-transform: uppercase;
}

.p1-article-header__title {
  font-size: var(--p1-text-3xl);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-md);
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-article-header__title { font-size: var(--p1-text-4xl); }
}

.p1-article-header__standfirst {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-xl);
  font-style: italic;
  line-height: var(--p1-leading-normal);
  margin-block-end: var(--p1-space-lg);
  text-wrap: pretty;
}

.p1-article-header[data-align="center"] .p1-article-header__inner { text-align: center; }
.p1-article-header[data-align="center"] .p1-article-header__standfirst {
  margin-inline: auto;
  max-inline-size: 32rem;
}

.p1-article-header__byline {
  align-items: center;
  display: flex;
  gap: var(--p1-space-sm);
}
.p1-article-header[data-align="center"] .p1-article-header__byline { justify-content: center; }

.p1-article-header__avatar {
  background: color-mix(in oklch, var(--p1-surface-inverse) 10%, transparent);
  block-size: 2.75rem;
  border-radius: var(--p1-radius-pill);
  flex: none;
  inline-size: 2.75rem;
  overflow: hidden;
}
.p1-article-header__avatar-img {
  block-size: 100%;
  inline-size: 100%;
  object-fit: cover;
}

.p1-article-header__author-info { text-align: start; }

.p1-article-header__author-name {
  color: var(--p1-fg-default);
  font-weight: var(--p1-weight-bold);
}

.p1-article-header__meta {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  margin-block-start: 0.125rem;
}

.p1-article-header__sep {
  color: var(--p1-border);
  margin-inline: var(--p1-space-xs);
}

.p1-article-header__rule {
  border: 0;
  border-block-start: 1px solid var(--p1-border);
  margin-block-start: var(--p1-space-lg);
}

